describe("doctests of sympy.core.sorting", () => {
  it("x.sort_key() == default_sort_key(x)", () => {
    expect(sympyStr(rational(1).equals(1))).toBe('True');
  });
  // a primitive result that no library call returned
  //   default_sort_key(UndefinedFunction('f'))
  //   => ((0, 0, 'UndefinedFunction'), (1, ('f',)), ((1, 0, 'Number'), (0, ()), (), 1), 1)
  it.todo("default_sort_key(UndefinedFunction('f'))");
  // a primitive result that no library call returned
  //   default_sort_key('1')
  //   => ((0, 0, 'str'), (1, ('1',)), ((1, 0, 'Number'), (0, ()), (), 1), 1)
  it.todo("default_sort_key('1')");
  // a primitive result that no library call returned
  //   default_sort_key(S.One)
  //   => ((1, 0, 'Number'), (0, ()), (), 1)
  it.todo("default_sort_key(S.One)");
  // a primitive result that no library call returned
  //   default_sort_key(2)
  //   => ((1, 0, 'Number'), (0, ()), (), 2)
  it.todo("default_sort_key(2)");
  it("a.sort_key() == a.sort_key('rev-lex')", () => {
    expect(sympyStr(rational(1).equals(1))).toBe('True');
  });
  it("eq.sort_key() == eq.sort_key('rev-lex')", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("eq.as_ordered_terms()", () => {
    const x = new Sym('x');
    expect(sympyStr([x, pow(x, -1)])).toBe('[x, 1/x]');
  });
  it("eq.as_ordered_terms('rev-lex')", () => {
    const x = new Sym('x');
    expect(sympyStr([pow(x, -1), x])).toBe('[1/x, x]');
  });
});

